class FEGraphicalMenu {
    char padding[0x160];
public:
    void Draw();
};

class FEMultiMenu : public FEGraphicalMenu {};

struct preformat_vtable {
    char padding[0x130];
    short adjustment;
    short padding2;
    void (*draw_line)(void *, int, float, float);
};

struct PreformatText {
    char padding[0x4c];
    preformat_vtable *vtable;
    char padding2[0x10];
    int actual_lines;

    void DrawLine(int line_num, float x1, float y1)
    {
        preformat_vtable *table = vtable;
        table->draw_line((char *)this + table->adjustment, line_num, x1, y1);
    }

    int GetActualLines() { return actual_lines; }
};

struct menu_system_vtable {
    char padding[0x20];
    short adjustment;
    short padding2;
    void (*make_active)(void *, int, int, bool);
};

struct GraphicalMenuSystem {
    char padding[0x8c];
    menu_system_vtable *vtable;
    enum { ExtrasMenu = 1 };

    void MakeActive(int menu, int submenu = 1, bool notify = true)
    {
        menu_system_vtable *table = vtable;
        table->make_active((char *)this + table->adjustment, menu, submenu, notify);
    }
};

class CreditsFrontEnd : public FEMultiMenu {
    PreformatText* credits;
    GraphicalMenuSystem* sys;
    static const int num_lines = 300;
    float first_line_y;
    float x_all;
    bool up_pressed;
    bool down_pressed;

public:
    void Draw();
};

void CreditsFrontEnd::Draw()
{
    FEMultiMenu::Draw();

    for(int i=0; i<num_lines; i++)
    {
        float y = first_line_y+i*20;
        if(y > -10 && y < 490) credits->DrawLine(i, x_all, y);
    }

    if(first_line_y+(credits->GetActualLines()-1)*20 < 0)
    {
        sys->MakeActive(GraphicalMenuSystem::ExtrasMenu);
    }
}
